const aggregationOptions = useMemo(() => {
    return GLOBAL_CONFIG.AGGREGATOR_LIST.map((op) => ({
        value: op,
        label: t(`constant.aggregator.${op}`),
    }));
}, []); // Add dependencies or remove useMemo if not necessary
```

